mapper.select:
WITH DailyEmotions AS ( SELECT DATE(t.occurred_at) as date, t.emotion_id, COUNT(*) as emotion_count, SUM(t.amount) as emotion_amount, MAX(t.occurred_at) as max_occurred_at FROM transactions t WHERE t.user_id = #{userId} AND t.type = 'EXPENSE' AND YEAR(t.occurred_at) = #{year}
AND MONTH(t.occurred_at) = #{month}
GROUP BY DATE(t.occurred_at), t.emotion_id ), RankedEmotions AS ( SELECT de.date, de.emotion_id, ROW_NUMBER() OVER ( PARTITION BY de.date ORDER BY de.emotion_count DESC, de.emotion_amount DESC, de.max_occurred_at DESC ) as rn FROM DailyEmotions de ), DailyStats AS ( SELECT DATE(t.occurred_at) as date, COUNT(*) as transaction_count, COALESCE(SUM(t.amount), 0) as total_expense FROM transactions t WHERE t.user_id = #{userId} AND t.type = 'EXPENSE' AND YEAR(t.occurred_at) = #{year}
AND MONTH(t.occurred_at) = #{month}
GROUP BY DATE(t.occurred_at) ) SELECT ds.date, ds.transaction_count, ds.total_expense, e.emotion_id, e.name AS emotion_name, e.color AS emotion_color FROM DailyStats ds JOIN RankedEmotions re ON ds.date = re.date AND re.rn = 1 JOIN emotions e ON re.emotion_id = e.emotion_id ORDER BY ds.date ASC

SELECT COALESCE(SUM(t.amount), 0)
FROM transactions t
WHERE t.user_id = #{userId}
  AND YEAR(t.occurred_at) = #{year}
  AND MONTH(t.occurred_at) = #{month}
  AND t.type = 'EXPENSE'
